/* prog48_sorted_linked_list.c
 *
 * Re‑implementation of the original program that builds a sorted linked list
 * from the command‑line arguments and prints the list.
 *
 * Behaviour:
 *   - If no numbers are supplied (argc < 2) it prints the line "EMPTY".
 *   - Otherwise each argument is interpreted as a signed decimal integer,
 *     inserted into a singly linked list in ascending order,
 *     and finally the list is printed as space‑separated values followed
 *     by a newline.  The first value is printed without a leading space,
 *     subsequent values are preceded by a single space.
 *
 * The original binary limited the list to 64 elements; this re‑implementation
 * simply ignores any arguments beyond the first 64, matching the observed
 * behaviour.
 */

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MAX_ELEMS 64          /* matches the original limit */

typedef struct Node {
    long value;
    struct Node *next;
} Node;

/* Insert a new node with the given value into the list so that the list
 * remains sorted in non‑decreasing order. */
static void sorted_insert(Node **head, Node *new_node)
{
    Node *prev = NULL;
    Node *cur  = *head;

    while (cur != NULL && cur->value <= new_node->value) {
        prev = cur;
        cur  = cur->next;
    }

    new_node->next = cur;
    if (prev == NULL) {
        *head = new_node;          /* insert at the front */
    } else {
        prev->next = new_node;     /* insert after prev */
    }
}

/* Print the list in the format required by the original program. */
static void print_list(Node *head)
{
    int first = 1;
    for (Node *p = head; p != NULL; p = p->next) {
        if (!first) {
            putchar(' ');
        }
        printf("%ld", p->value);
        first = 0;
    }
    putchar('\n');
}

/* Simple node pool to avoid dynamic allocation limits of the original. */
static Node node_pool[MAX_ELEMS];
static int  pool_used = 0;

/* Allocate a node from the static pool; returns NULL if the pool is exhausted. */
static Node *alloc_node(void)
{
    if (pool_used >= MAX_ELEMS)
        return NULL;
    return &node_pool[pool_used++];
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    Node *head = NULL;

    for (int i = 1; i < argc && pool_used < MAX_ELEMS; ++i) {
        char *endptr = NULL;
        long  val    = strtol(argv[i], &endptr, 10);
        (void)endptr;               /* original program ignored conversion errors */

        Node *n = alloc_node();
        if (n == NULL)               /* pool exhausted – stop processing further args */
            break;
        n->value = val;
        n->next  = NULL;

        sorted_insert(&head, n);
    }

    if (head == NULL) {
        puts("EMPTY");
    } else {
        print_list(head);
    }

    return 0;
}
